from dataclasses import dataclass
from .enums import Animation, Speed, Brightness, RainbowMode, Sleep

# data class of base config for usb report 
@dataclass
class Config:
    ANIMATION_TYPE: Animation
    ANIMATION_SPEED: Speed
    ANIMATION_BRIGHTNESS: Brightness
    ANIMATION_GREEN: int
    ANIMATION_RED: int
    ANIMATION_BLUE: int
    ANIMATION_RAINBOW: RainbowMode
    ANIMATION_SLEEP_DURATION: Sleep

    def __init__(self, animation: Animation, speed: Speed, brightness: Brightness, red: int, green: int, blue: int, is_rainbow: RainbowMode, sleep: Sleep) -> None:
        self.ANIMATION_TYPE = animation
        self.ANIMATION_SPEED = speed
        self.ANIMATION_BRIGHTNESS = brightness
        self.ANIMATION_RED = red
        self.ANIMATION_GREEN = green
        self.ANIMATION_BLUE = blue
        self.ANIMATION_RAINBOW = is_rainbow
        self.ANIMATION_SLEEP_DURATION = sleep
    
    def update(self, var: dict):
        self.ANIMATION_TYPE = Animation.from_value("neon_stream" if var['animation'] == None else var['animation'])
        self.ANIMATION_SPEED = Speed.from_value(5 if var['speed'] == None else int(var['speed']))
        self.ANIMATION_BRIGHTNESS = Brightness.from_value(5 if var['brightness'] == None else int(var['brightness']))
        self.ANIMATION_RED = int(255 if var['red'] == None else var['red'])
        self.ANIMATION_GREEN = int(255 if var['green'] == None else var['green'])
        self.ANIMATION_BLUE = int(255 if var['blue'] == None else var['blue'])
        self.ANIMATION_RAINBOW = RainbowMode.from_value(var['rainbow'])
        self.ANIMATION_SLEEP_DURATION = Sleep.from_value(5 if var['sleep'] == None else int(var['sleep']))

    def reports(self) -> list[bytearray]:
        p1_hex = '058300000000'
        p1 = bytearray.fromhex(p1_hex)
        p2_hex = ''
        p2 = bytearray.fromhex(p2_hex)
        p3_hex = ''
        p3 = bytearray.fromhex(p3_hex)
        p4_hex = '0584c8000000'
        p4 = bytearray.fromhex(p4_hex)
        p5_hex = ''
        p5 = bytearray.fromhex(p5_hex)
        p6_hex = ''
        p6 = bytearray.fromhex(p6_hex)

        # Flood the entire color matrix in P3 (bytes 29 to 301) with the target color
        # This ensures animations that read from any key (like Retro Snake) pick up the correct color.
        for i in range(29, 302, 3):
            p3[i] = self.ANIMATION_BLUE
            p3[i+1] = self.ANIMATION_GREEN
            p3[i+2] = self.ANIMATION_RED

        # The animation specific parameters (Rainbow Mode and Speed/Brightness)
        # are stored in an array of pairs in both P2 and P6.
        # The array starts such that the Rainbow byte for animation N is at 32 + N*2.
        # The Parameter byte is at 33 + N*2.
        # The Parameter byte encodes BOTH Speed and Brightness!
        # Bits 4-7 (Upper nibble): Speed (0 to 4, representing speeds 1 to 5)
        # Bits 0-3 (Lower nibble): Brightness (0 to 3, representing 25% to 100%)
        anim_n = self.ANIMATION_TYPE.value
        rainbow_byte = self.ANIMATION_RAINBOW.value
        
        # Ensure values are within bounds
        speed_val = max(1, min(5, self.ANIMATION_SPEED.value))
        bright_val = max(1, min(4, self.ANIMATION_BRIGHTNESS.value))
        
        param_byte = ((speed_val - 1) << 4) | (bright_val - 1)

        # Inject into P2 (Saved State Profile)
        p2[32 + anim_n * 2] = rainbow_byte
        p2[33 + anim_n * 2] = param_byte

        # Inject into P6 (Active State Profile)
        p6[32 + anim_n * 2] = rainbow_byte
        p6[33 + anim_n * 2] = param_byte

        # Set animation mode in P6 at offset 21
        p6[21] = anim_n

        return [p1, p2, p3, p4, p5, p6]

def get_base_config() -> Config:
    config = Config(
        Animation.NEON_STREAM,
        Speed.SPEED_5,
        Brightness.BRIGHTNESS_5,
        255,
        255,
        255,
        RainbowMode.OFF,
        Sleep.SLEEP_NEVER
    )
    return config